def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

def remove_duplicates(lst):
    seen = set()
    out = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def second_largest(nums):
    unique = sorted(set(nums), reverse=True)
    return unique[1] if len(unique) > 1 else None

def flatten(nested):
    out = []
    for sub in nested:
        out.extend(sub)
    return out

def average(nums):
    if not nums:
        return 0
    return sum(nums) / len(nums)

def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)

def count_words(text):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return counts

def string_length(s):
    count = 0
    for _ in s:
        count += 1
    return count

def total(prices):
    total = 0
    for p in prices:
        total += p
    return total

def append_to(item, target=None):
    if target is None:
        target = []
    target.append(item)
    return target

def check(n):
    if n > 5:
        return 'big'
